var busy = new LabPttController { Busy = true };
bool accepted = busy.Press(0); // false：本地 Busy 擋住

var c = new LabPttController { RequireGrant = true };
c.Press(10);
int old = c.Epoch;
c.Release(20); c.Press(30);
c.Grant(old, 40);          // 舊請求，不使本次 Keying
c.Grant(c.Epoch, 50);      // 本次請求，進入 Keying
// Ready 仍是另一項設備狀態條件
